package com.example.bandlink.repository; import com.example.bandlink.entity.Conversation; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ConversationRepository extends JpaRepository<Conversation,Long>{Optional<Conversation> findByUserAIdAndUserBId(Long a,Long b); List<Conversation> findByUserAIdOrUserBIdOrderByLastMessageAtDesc(Long a,Long b);}
